action.code:
if (open_list_.empty()) {
    return nullptr;
}

auto lowest_node = std::min_element(open_list_.begin(), open_list_.end(),
    [](const RouteModel::Node* a, const RouteModel::Node* b) {
        return (a->g_value + a->h_value) < (b->g_value + b->h_value);
    });

auto it = std::find(open_list_.begin(), open_list_.end(), *lowest_node);
if (it != open_list_.end()) {
    open_list_.erase(it);
}

return *lowest_node;

